        public static void HandlePacket(byte[] packet, GameState client) {
            var gData = new Data(false);
            gData.Deserialize(packet);
            if (packet == null)
                return;
            if (client == null)
                return;
            var Length = BitConverter.ToUInt16(packet, 0);
            var ID = BitConverter.ToUInt16(packet, 2);

            if (client.Filtering)
                if (client.PacketFilter.Filter(ID))
                    return;

            if (ClientSeal != BitConverter.ToUInt64(packet, Length)) {
                client.Disconnect();
                return;
            }

            switch (ID) {
                case 1107 when client.Map.BaseID == 700:
                case 1056 when client.Entity.MapID is 1234 or 1235 or 1236 or 1237 or 1238:
                case 1009 when client.Action != 2:
                    return;
                case 1009: {
                    var usage = new ItemUsage(false);
                    usage.Deserialize(packet);
                    if (usage.ID == ItemUsage.Ping) {
                        client.Send(usage);
                        return;
                    }

                    break;
                }
            }

            // Check if any active event wants to handle this packet
            // Only intercept if the handler actually processes it (returns true)
            // For Data packets (10010), pass the command ID (gData.ID) instead of the packet type
            var packetIdForEvent = (ID == 10010) ? (ushort)gData.ID : ID;
            foreach (var gameEvent in EventScheduler.GetAllEvents()) {
                if (gameEvent.IsActive && gameEvent.HandlePacket(client, packet, packetIdForEvent)) {
                    return; // Packet was handled by event
                }
            }

            var _stream = new BinaryReader(new MemoryStream(packet));
            switch (ID) {
                #region [3251-3255] Perfection

                case 3251: {
                    var Pr = new PerfectionItems();
                    var p = new byte[packet.Length - 8];
                    for (var i = 0; i < p.Length; i++) {
                        p[i] = packet[i];
                    }

                    if (Pr.R(p))
                        Pr.Handle(p, client);
                    break;
                }
                case 3253: {
                    var pkt = new PerfectionScore();
                    var myPacket = new byte[packet.Length - 8];
                    for (var i = 0; i < myPacket.Length; i++) {
                        myPacket[i] = packet[i];
                    }

                    if (pkt.Read(myPacket))
                        pkt.Handle(client);
                    break;
                }
                case 3255: {
                    var Pr = new PerfectionGUI();
                    var p = new byte[packet.Length - 8];
                    for (var i = 0; i < p.Length; i++) {
                        p[i] = packet[i];
                    }

                    if (Pr.R(p))
                        Pr.Handle(client);
                    break;
                }
                case 3256: {
                    var pkt = new PerfectionRank();
                    var myPacket = new byte[packet.Length - 8];
                    for (var i = 0; i < myPacket.Length; i++) {
                        myPacket[i] = packet[i];
                    }

                    if (pkt.Read(myPacket))
                        pkt.Handle(client);
                    break;
                }
                case 3257: {
                    switch (packet[5]) {
                        case 0: {
                            if (PrestigeRank.S != null)
                                client.Send(PrestigeRank.S);
                            break;
                        }
                        case 1: {
                            var uid = PrestigeRank.R(packet)[2];
                            client.Send(!Kernel.GamePool.TryGetValue(uid, out var value)
                                ? PrestigeRank.Offline
                                : WindowStats(value).ToArray());
                            break;
                        }
                    }

                    break;
                }

                #endregion

                #region Coatstorage & Titlestorage (3300) && (3301)

                case 3300: {
                    var pkt = new CoatStorage();

                    var myPacket = new byte[packet.Length - 8];

                    for (var i = 0; i < myPacket.Length; i++) {
                        myPacket[i] = packet[i];
                    }

                    if (pkt.Read(myPacket)) {
                        pkt.Handle(client);
                    }

                    break;
                }
                case 3301: {
                    var pkt = new TitleStorage();

                    var myPacket = new byte[packet.Length - 8];

                    for (var i = 0; i < myPacket.Length; i++) {
                        myPacket[i] = packet[i];
                    }

                    if (pkt.Read(myPacket)) {
                        pkt.Handle(client);
                    }

                    break;
                }

                #endregion

                #region Transfer

                case 2900: {
                    switch (packet[4]) {
                        case 0: {
                            uint[] array = [37, 43];
                            var Buffer = new byte[6 + 8 + 5 * array.Length];
                            Writer.Ushort((ushort)(Buffer.Length - 8), 0, Buffer);
                            Writer.Ushort(2901, 2, Buffer);
                            Buffer[5] = (byte)array.Length;
                            var offset = 6;
                            foreach (var t in array) {
                                Writer.Uint(t, offset, Buffer);
                                offset += 4;
                                Buffer[offset] = 1;
                                offset += 1;
                            }

                            client.Send(Buffer);
                            break;
                        }
                        default:
                            PrintPacket(packet);
                            break;
                    }

                    break;
                }
                case 2902: {
                    if (Program.ServerTransfer) {
                        if (!Kernel.TransferredPlayers.Contains(client.Entity.UID))
                            Kernel.TransferredPlayers.Add(client.Entity.UID);
                        var serverid = packet[5];
                        client.Disconnect();
                    }
                    else
                        client.MessageBox("You Can't Transefer Now");

                    break;
                }

                #endregion

                #region Mentor prize

                case 2067: {
                    MentorPrize.Process(packet, client);
                    break;
                }

                #endregion

                #region Roulette packets (2800 - 2810)

                case GamePackets.Roulette.GamePackets.MsgRouletteSignUp: {
                    MsgRouletteSignUp.Poroces(client, packet);
                    break;
                }
                case GamePackets.Roulette.GamePackets.MsgRouletteCheck: {
                    MsgRouletteCheck.Poroces(client, packet);
                    break;
                }
                case GamePackets.Roulette.GamePackets.MsgRouletteAction: {
                    MsgRouletteAction.Poroces(client, packet);
