                case 1135: {
                    var quest = new QuestData(true);
                    quest.Deserialize(packet);
                    break;
                }
                case 1134: {
                    var quest = new QuestPacket(false);
                    quest.Deserialize(packet);
                    switch (quest.Action) {
                        case QuestPacket.QuestAction.Begin: {
                            if (client.Quests.AllowAccept())
                                client.Quests.Accept(quest[0].UID);
                            client.Send(quest);
                            break;
                        }
                        case QuestPacket.QuestAction.List: {
                            if (quest.Amount < 80)
                                client.Quests.SendFullGUI();
                            break;
                        }
                    }

                    break;
                }

