                #region MentorGain PrizePacket.

                case 1036: {
                    var prize = new PrizeClaimb(false);
                    prize.Deserialize(packet);
                    switch (prize.Type) {
                        case 0: {
                            prize = new PrizeClaimb(true) {
                                OnlineTrainingExper = client.Entity.OnlineTrainning,
                                HuntingExper = client.Entity.HuntingExp
                            };
                            prize.Send(client);
                            break;
