                #region NpcSpawn (2030)

                case 2030: {
                    if (client.Action != 2)
                        return;
                    var spawn = new NpcSpawn(false);
                    spawn.Deserialize(packet);
                    var Base = new SobNpcSpawn {
                        Owner = client,
                        UID = client.Map.EntityUIDCounter2.Next,
                        Mesh = spawn.Mesh,
                        MapID = client.Entity.MapID,
                        X = spawn.X,
                        Y = spawn.Y
                    };

                    if (client.spwansitem != null) {
                        uint id;
                        id = client.spwansitem.ID;
                    }

                    if ((spawn.Mesh / 10) == 147) {
                        var UID = client.Entity.OnMoveNpc;
                        if (client.Guild != null || client.Account.State == AccountTable.AccountState.GM) {
                            if (client.AsMember is { Rank: Enums.GuildMemberRank.GuildLeader } ||
                                client.Account.State == AccountTable.AccountState.GM) {
                                if (client.Guild.Name is { } and not "") {
                                    if (client.Guild.Name == GuildWar.Pole.Name ||
                                        client.Account.State == AccountTable.AccountState.GM) {
                                        var getnpc = GuildCondutors.GuildConductors[UID];
                                        var oldx = getnpc.npc.X;
                                        var oldy = getnpc.npc.Y;
                                        var oldmap = getnpc.npc.MapID;

                                        if (!GuildCondutors.MoveNpc(getnpc.npc.UID, client.Entity.MapID, spawn.X,
                                                spawn.Y))
                                            client.Entity.SendSysMesage(
                                                "Invalid New location ! or Invalid map, try again ");
                                        else {
                                            var removeoldnpc = new Data(true) { UID = UID, ID = Data.RemoveEntity };

                                            Kernel.SendWorldMessage(removeoldnpc, Program.Values, oldmap);
                                            // var dictionary = Kernel.GamePool.Values.Where((play) => play.Entity.MapID == oldmap && Kernel.GetDDistance(play.Entity.X, play.Entity.Y, oldx, oldy) <= 17);
                                            // foreach (var pclient in dictionary)
                                            //     pclient.Send(removeoldnpc);

                                            client.Map.RemoveNpc(getnpc.npc, true);

                                            var newmap = Kernel.Maps[client.Entity.MapID];
                                            newmap.AddNpc(getnpc.npc, true
                                            );
                                            client.SendScreen(getnpc.npc.ToArray());
                                        }
                                    }
                                    else
                                        client.Entity.SendSysMesage("Sorry, you guild not dominate the Guild War");
                                }
                                else
                                    client.Entity.SendSysMesage("Sorry, you guild not dominate the Guild War");
                            }
                            else
                                client.Entity.SendSysMesage("Sorry, you guild not dominate the Guild War");
                        }
                        else
                            client.Entity.SendSysMesage("Sorry, you guild not dominate the Guild War");
                    }
                    else if (client.Entity.MapID == 1038) {
                        var _buffer = new byte[client.Entity.SpawnPacket.Length];
                        Buffer.BlockCopy(client.Entity.SpawnPacket, 0, _buffer, 0, client.Entity.SpawnPacket.Length);
                        Base.SpawnPacket = _buffer;
                        Base.Type = spawn.Type;
                        Base.ShowName = true;
                        Base.Name = client.Entity.Name;
                        Base.Hitpoints = Base.MaxHitpoints = 2000000;
                        client.Map.Statues.TryAdd(Base.UID, Base);
                        client.Map.Npcs.TryAdd(Base.UID, Base);

                        #region Save statue

                        using (var cmd = new MySqlCommand(MySqlCommandType.INSERT).Insert("statues")
                                   .Insert("id", Base.UID).Insert("lookface", Base.Mesh)
                                   .Insert("type", (byte)Base.Type).Insert("cellx", Base.X).Insert("celly", Base.Y)
                                   .Insert("mapid", Base.MapID).Insert("name", Base.Name)
                                   .Insert("life", Base.Hitpoints).Insert("maxlife", Base.MaxHitpoints))
                            cmd.Execute();

                        var stream = new MemoryStream();
                        var writer = new BinaryWriter(stream);
                        writer.Write(Base.SpawnPacket);
                        var SQL = "UPDATE `statues` SET SpawnPacket=@SpawnPacket, where UID = " + Base.UID + " ;";
                        var rawData = stream.ToArray();
                        using (var conn = DataHolder.MySqlConnection) {
                            conn.Open();
                            using (var cmd = new MySql.Data.MySqlClient.MySqlCommand()) {
                                cmd.Connection = conn;
                                cmd.CommandText = SQL;
                                cmd.Parameters.AddWithValue("@SpawnPacket", rawData);
                                cmd.ExecuteNonQuery();
                            }
                        }

                        #endregion
                    }
                    else if (House.Houses.ContainsKey(client.Entity.UID)) {
                        if ((spawn.Mesh / 10) == 820)
                            Base.Type = (Enums.NpcType)2;
                        else
                            Base.Type = (Enums.NpcType)26;
                        // client.Map.AddNpc(Base);
                        var itembox = House.CheckItemBox(client, House.Houses[client.Entity.UID]);
                        if (itembox != null) {
                            client.MessageBox("You already Have ItemBox in your House");
                            return;
                        }

                        do {
                            Base.UID = client.Map.EntityUIDCounter2.Next;
                        } while (House.Houses[client.Entity.UID].Furnitures.ContainsKey(Base.UID));

                        House.Houses[client.Entity.UID].Furnitures.Add(Base.UID, Base);
                        House.SaveFurnitures(client);
                    }

                    if (client.Entity.MapID != 1038)
                        client.Inventory.Remove(client.spwansitem, Enums.ItemUse.Remove);
                    client.SendScreenSpawn(Base, true);
                    break;
                }

