                        if (Created) {
                            client.JustCreated = true;
                            client.Send(new Message(Message, "ALLUSERS", Color.Orange, GamePackets.Message.PopUP));
                        }
                        else {
                            client.Send(new Message(Message, "ALLUSERS", Color.Orange, GamePackets.Message.PopUP));
                        }
                    }

                    break;
                }

