                    if (message.__Message.Split(["\\n"], StringSplitOptions.RemoveEmptyEntries).Length >
                        0)
                        message.__Message =
                            message.__Message.Split(["\\n"], StringSplitOptions.RemoveEmptyEntries)[0];
                    Chat(message, client);
                    break;
                }

