                            client.Entity.InAutoHunt = false;
                            client.Send(auto);
                            return;
                        }
                    }

                    return;
                }

                #endregion AutoHunting (1070)

                #region Advertise

                case 2226: {
                    //0,4,8

                    uint all_advertise = (ushort)Guild.Advertise.AdvertiseRanks.Length;

                    var Receive_count = BitConverter.ToUInt32(packet, 4);
                    if (Receive_count != 0 && Receive_count % 4 != 0)
                        return;

                    List<Guild> AdvGuilds = [];
                    for (ushort x = 0; x < 4; x++) {
                        var getposition = (ushort)(Receive_count + x);
                        if (Guild.Advertise.AdvertiseRanks.Length <= getposition)
                            break;
                        AdvGuilds.Add(Guild.Advertise.AdvertiseRanks[getposition]);
                    }


                    if (AdvGuilds.Count <= 2) {
                        var adv = new Advertise((ushort)AdvGuilds.Count) {
                            AllRegistred = (ushort)Guild.Advertise.AdvertiseRanks.Length,
                            AtCount = (ushort)Receive_count,
                            PacketNo = 1
                        };

                        for (ushort x = 0; x < AdvGuilds.Count; x++) {
                            var element = AdvGuilds[x];
                            adv.Aprend(element);
                        }

                        client.Send(adv.ToArray());
                    }
                    else if (AdvGuilds.Count == 3) {
                        var adv = new Advertise(2) {
                            AllRegistred = (ushort)Guild.Advertise.AdvertiseRanks.Length,
                            AtCount = (ushort)Receive_count,
                            PacketNo = 1
                        };

                        for (ushort x = 0; x < 2; x++) {
                            var element = AdvGuilds[x];
                            adv.Aprend(element);
                        }

                        client.Send(adv.ToArray());

                        var ndadv = new Advertise(1) {
                            AllRegistred = (ushort)Guild.Advertise.AdvertiseRanks.Length,
                            AtCount = (ushort)Receive_count
                        };

                        ndadv.Aprend(AdvGuilds.Last());
                        client.Send(ndadv.ToArray());
                    }
                    else if (AdvGuilds.Count == 4) {
                        var adv = new Advertise(2) {
                            AllRegistred = (ushort)Guild.Advertise.AdvertiseRanks.Length,
                            AtCount = (ushort)Receive_count,
                            PacketNo = 1
                        };
                        for (ushort x = 0; x < 2; x++) {
                            var element = AdvGuilds[x];
                            adv.Aprend(element);
                        }

                        client.Send(adv.ToArray());


                        var ddddadv = new Advertise(2) {
                            AllRegistred = (ushort)Guild.Advertise.AdvertiseRanks.Length,
                            AtCount = (ushort)Receive_count
                        };

                        for (ushort x = 2; x < 4; x++) {
                            var element = AdvGuilds[x];
                            ddddadv.Aprend(element);
                        }

                        client.Send(ddddadv.ToArray());
                    }

                    break;
                }
                case 2225: {
                    if (client.Guild == null) return;
                    if (client.AsMember is not { Rank: Enums.GuildMemberRank.GuildLeader }) return;


                    var GuildID = BitConverter.ToUInt32(packet, 4);
                    var buletin = ReadString(packet, 8, 254);
                    ulong donation = BitConverter.ToUInt32(packet, 264);
                    var Auto_join = packet[272] == 1;
                    var Level = packet[274];
                    var Reborn = packet[276];
                    var Flag = BitConverter.ToUInt16(packet, 278);
                    var Grade = packet[280];
                    if (buletin.Contains('^')) {
                        client.Entity.SendSysMesage(
                            "you buletin contain invalid char (^)! Please change this, to use my services");
                        break;
                    }

                    if (client.Guild.SilverFund >= donation) {
                        client.Guild.SilverFund -= donation;
                        client.Guild.AdvertiseRecruit.Buletin = buletin;
                        client.Guild.AdvertiseRecruit.AutoJoin = Auto_join;
                        client.Guild.AdvertiseRecruit.Level = Level;
                        client.Guild.AdvertiseRecruit.Reborn = Reborn;
                        client.Guild.AdvertiseRecruit.SetFlag(Flag, Guild.Recruitment.Mode.Recruit);
                        client.Guild.AdvertiseRecruit.Grade = Grade;
                        client.Guild.AdvertiseRecruit.Donations += donation;

                        Guild.Advertise.Add(client.Guild);
                        GuildTable.SaveAdvertise(client.Guild);
                    }
                    else {
                        client.Entity.SendSysMesage("you guild use small donation!");
                    }

                    break;
                }
                case 2227: {
                    switch (packet[4]) {
                        case 2: //open gui
                        {
                            var sendgui = new byte[288];
                            Writer.WriteUInt16(280, 0, sendgui);
                            Writer.WriteUInt16(2225, 2, sendgui);
                            client.Send(sendgui);
                            break;
                        }
                        case 1: //join
                        {
                            if (client.Entity.GuildID == 0) {
                                var GuildID = BitConverter.ToUInt32(packet, 8);

                                if (Kernel.Guilds.TryGetValue(GuildID, out var guild)) {
                                    if (guild.AdvertiseRecruit.AutoJoin) {
                                        if (guild.AdvertiseRecruit.Compare(client.Entity,
                                                Guild.Recruitment.Mode.Recruit))
                                            guild.AddMember(client);
                                    }
                                }
                            }

                            break;
                        }
                    }

                    break;
                }

                #endregion

                #region WarehousePassword (2261)

                case 2261: {
                    var whp = new WareHousePassword(false);
                    whp.Deserialize(packet);
                    switch (whp.type) {
                        // Creating new password
                        case WareHousePassword.SetNewPass: {
                            if (client.WarehousePW == 0) {
                                client.WarehouseOpen = true;
                                client.WarehousePW = whp.NewPassword;
                                whp = new WareHousePassword(true) {
                                    type = WareHousePassword.PasswordCorrect,
                                    OldPassword = 0x0101
                                };
                                client.Send(whp);
                                client.Send(new Message("Your warehouse password has been successfully set!", Color.Red,
                                    Message.System));
                            }

                            return;
                        }
                        // Change password
                        case WareHousePassword.SendInformation: {
                            if (client.WarehousePW != 0) {
                                if (client.WarehousePW == whp.OldPassword) {
                                    client.WarehouseOpen = true;
                                    client.WarehousePW = whp.NewPassword;
                                    whp = new WareHousePassword(true) {
                                        type = WareHousePassword.PasswordCorrect,
                                        OldPassword = 0x0101
                                    };
                                    client.Send(whp);
                                    client.Send(new Message("Your warehouse password has been successfully modified!",
                                        Color.Red, Message.System));
                                }
                                else {
                                    whp = new WareHousePassword(true) {
                                        type = WareHousePassword.PasswordWrong,
                                        OldPassword = 0x01
                                    };
                                    client.Send(whp);
                                }
                            }

                            return;
                        }
                        // Forget password
                        case 2: {
                            if (client.WarehousePW != 0) {
                                client.WarehousePW = 0;
                                client.Send(new Message("Your warehouse password has been successfully removed!",
                                    Color.Red, Message.System));
                            }

                            break;
                        }
                        // Entering correct password
                        case WareHousePassword.VerifiedPassword: {
                            if (client.WarehousePW != 0) {
                                if (client.WarehousePW == whp.NewPassword) {
                                    client.WarehouseOpen = true;
                                    whp = new WareHousePassword(true) {
                                        type = WareHousePassword.PasswordCorrect,
                                        OldPassword = 0x0101
                                    };
                                    client.Send(whp);
                                }
                                else {
                                    whp = new WareHousePassword(true) {
                                        type = WareHousePassword.PasswordWrong
                                    };
                                    client.Send(whp);
                                }
                            }
                            else {
                                client.Disconnect();
                            }

                            return;
                        }
                        default: {
                            Console.WriteLine("Unknown 2261 packet type " + whp.type);
                            return;
                        }
                    }

                    return;
                }

                #endregion

                #region PK Explorer (2220)

                case 2220: {
                    var pk = new PkExplorer(packet, client) {
                        SubType = 1
                    };
                    client.Send(pk.Build());
                    break;
                }

                #endregion

                #region New Lottery

                case 1314: {
                    var I = new newLottery(true);
                    I.Deserialize(packet);

                    switch (packet[4]) {
                        case (byte)newLottery.Accept: {
                            if (client.Entity.LOTOITEM != null) {
                                if (client.Entity.LOTOITEM.Sockets == 1)
                                    client.Inventory.Add(client.Entity.LOTOITEM.ID, client.Entity.LOTOITEM.Plus, 1, 255,
                                        0);
                                else if (client.Entity.LOTOITEM.Sockets == 2)
                                    client.Inventory.Add(client.Entity.LOTOITEM.ID, client.Entity.LOTOITEM.Plus, 1, 255,
                                        255);
                                else
                                    client.Inventory.Add(client.Entity.LOTOITEM.ID, client.Entity.LOTOITEM.Plus, 1, 0,
                                        0);

                                client.Entity.AddJade = 0;
                                //   I.times = (ushort)(10 - client.LotteryEntries);
                                client.Send(I);
                                if (client.Entity.LOTOITEM.Plus >= 6 || client.Entity.LOTOITEM.Sockets == 2)
                                    Kernel.SendWorldMessage(new Message(
                                        "Congratulations! " + client.Entity.Name + " Won " +
                                        client.Entity.LOTOITEM.Name + " in Lottery.", Color.Black, Message.Talk));

                                client.Entity.LOTOITEM = null;
                            }

                            break;
                        }
                        case (byte)newLottery.AddJade: {
                            var rand = Kernel.Random.Next(LotteryTable.LotteryItems.Count);
                            var item = LotteryTable.LotteryItems[rand];
                            client.Inventory.Remove(711504, 1);
                            I.boxid = 3;
                            I.ItemID = item.ID;
                            client.Entity.AddJade += 1;
                            I.JadesAdded = client.Entity.AddJade;
                            if (item.Sockets > 0)
                                I.SocketGem1 = 255;
                            if (item.Sockets > 1)
                                I.SocketGem2 = 255;
                            //I.times = (ushort)(10 - client.LotteryEntries);
                            client.Entity.LOTOITEM = item;
                            I.plus = item.Plus;
                            client.Send(I);

                            break;
                        }
                        case (byte)newLottery.Continue: {
                            if (client.LotteryEntries < 10) {
                                client.LotteryEntries += 1;
                                client.Entity.AddJade = 0;
                                client.Inventory.Remove(711504, 3);

                                var rand = Kernel.Random.Next(LotteryTable.LotteryItems.Count);
                                var item = LotteryTable.LotteryItems[rand];

                                var tobesent = new newLottery(true) {
                                    boxid = 3,
                                    ItemID = item.ID
                                };
                                client.Entity.LOTOITEM = item;
                                tobesent.JadesAdded = client.Entity.AddJade;
                                tobesent.plus = item.Plus;
                                if (item.Sockets > 0)
                                    I.SocketGem1 = 255;
                                if (item.Sockets > 1)
                                    I.SocketGem2 = 255;
                                //  tobesent.times = (ushort)(10 - client.LotteryEntries);
                                client.Send(tobesent);
                            }

                            break;
                        }
                        default:
                            Console.WriteLine("20 " + packet[20]);
                            break;
                    }

                    break;
                }

