                #region ChangeName (2080)

                case 0x820:
                    var change = new NameChange(false);
                    change.Deserialize(packet);
                    if (change.Action == NameChange.NameChangeAction.Request) {
                        var name = Encoding.Default.GetString(packet, 10, 0x10).TrimEnd(new char[1]);
                        packet[6] = (byte)client.namechanges;
                        packet[8] = (byte)(100 - client.namechanges);
                        change.Send(client);
                        client.Send(change);
                        if (name is not "" and not "") {
                            if (!Npcs.InvalidCharacters(name) || !Npcs.InvalidCharacters3(name) || name.Contains("[") ||
                                name.Contains("]")) {
                                var reply = new NpcReply(6,
                                    "im sorry not allowed now close the dialog and try again") {
                                    OptionID = 0xff
                                };
                                client.Send(reply.ToArray());
                                return;
                            }

                            var reader = new MySqlReader(new MySqlCommand(MySqlCommandType.SELECT)
                                .Select("entities").Where("name", name));
                            if (reader.Read()) {
                                packet[4] = 2;
                                change.Send(client);
                                client.Send(change);
                                return;
                            }

                            if (client.Entity.ConquerPoints >= Rates.ChangeName) {
                                client.Entity.ConquerPoints -= Rates.ChangeName;
                                //    Database.MySqlCommand command3 = new Database.MySqlCommand(Database.MySqlCommandType.UPDATE);
                                //   command3.Update("entities").Set("namechange", name).Where("UID", (long)client.Entity.UID).Execute();                               
                                client.NewName = name;
                                Console.WriteLine(client.Entity.Name + ", Changed hes Name to : " + name);
                                Kernel.SendWorldMessage(
                                    new Message(
                                        client.Entity.Name + ", Changed He's/Hers Name to " + name +
                                        ", Will be affected after Maint.", Color.Red, 0x7d0), Program.Values);
                                client.namechanges += 1;
                                packet[4] = 1;
                                change.Send(client);
                                client.Send(change);
                                var reply = new NpcReply(6,
                                    "Your new name is : " + name + ", After server Restart You will get your new name.") {
                                    OptionID = 0xff
                                };
                                client.Send(reply.ToArray());
                                client.ChangeName(client);
                            }
                            else {
                                var reply =
                                    new NpcReply(6, "Come back when you have " + Rates.ChangeName + " CPS.") {
                                        OptionID = 0xff
                                    };
                                client.Send(reply.ToArray());
                            }
                        }
                    }

                    return;

                #endregion ChangeName (2080)

                #region vipteleport

                case 1128: {
                    if (client.Entity.MapID == 601) return;
                    if (client.Map.BaseID is 6000 or 6001 or 1844 or 1801 or 8883 ||
                        client.Map.BaseID == 1005 && client.Entity.MapID != 1005 || client.Map.BaseID == 700) {
                        client.Send(Constants.vipteleport);
                        return;
                    }

                    var tele = new VIPTeleport();
                    tele.Deserialize(packet);
                    switch (tele.TeleportType) {
                        case VIPTeleportTypes.SelfTeleport: {
                            if (Constants.MemoryAgateNotAllowedMap.Contains(client.Map.BaseID)) {
                                client.Send(Constants.Noteleport);
                                return;
                            }

                            if (Time32.Now > client.LastVIPTeleport.AddSeconds(1)) {
                                client.LastVIPTeleport = Time32.Now;
                                Teleport(client, tele.Location);
                                if (Constants.MemoryAgateNotAllowedMap.Contains(client.Entity.MapID)) {
                                    client.Entity.PreviousTeleport();
                                    client.Send(Constants.Noteleport);
                                    return;
                                }
                            }
                            else
                                client.Send(new Message(
                                    $"You have to wait {(client.LastVIPTeleport.AddSeconds(1) - Time32.Now).AllSeconds()} more seconds to use the VIP Teleport.",
                                    Color.Red,
                                    Message.Talk));

                            break;
                        }
                        case VIPTeleportTypes.TeamTeleport: {
                            if (Constants.MemoryAgateNotAllowedMap.Contains(client.Map.BaseID)) {
                                client.Send(Constants.Noteleport);
                                return;
                            }

                            if (Time32.Now > client.LastVIPTeamTeleport.AddSeconds(1)) {
                                client.LastVIPTeamTeleport = Time32.Now;
                                if (client.Team != null) {
                                    foreach (var teammate in client.Team.Teammates) {
                                        if (teammate.Entity.UID != client.Entity.UID) {
                                            teammate.Send(new VIPTeleport() {
                                                Countdown = 10,
                                                Location = tele.Location,
                                                Name = client.Entity.Name,
                                                TeleportType = VIPTeleportTypes.TeammateConfirmation
                                            }.ToArray());
                                        }
                                    }
                                }

                                Teleport(client, tele.Location);
                                if (Constants.MemoryAgateNotAllowedMap.Contains(client.Entity.MapID)) {
                                    client.Entity.PreviousTeleport();
                                    client.Send(Constants.Noteleport);
                                    return;
                                }
                            }
                            else
                                client.Send(new Message(
                                    $"You have to wait {(client.LastVIPTeamTeleport.AddSeconds(1) - Time32.Now).AllSeconds()} more seconds to use the VIP Team Teleport.",
                                    Color.Red, Message.Talk));

                            break;
                        }
                        case VIPTeleportTypes.TeammateTeleport: {
                            if (Constants.MemoryAgateNotAllowedMap.Contains(client.Map.BaseID)) {
                                client.Send(Constants.Noteleport);
                                return;
                            }

                            Teleport(client, tele.Location);
                            if (Constants.MemoryAgateNotAllowedMap.Contains(client.Entity.MapID)) {
                                client.Entity.PreviousTeleport();
                                client.Send(Constants.Noteleport);
                                return;
                            }

                            break;
                        }
                    }

                    break;
                }

