        public static bool PassRequeriments(SubClass Sc, Entity Entity) {
            var Pass = false;
            byte Level = 0;
            byte Reborns = 0;

            #region [Switch Phases]

            switch (Sc.Phase) {
                case 0:
                case 1: return true;
                case 2:
                    Level = 90;
                    Reborns = 0;
                    break;
                case 3:
                    Level = 110;
                    Reborns = 0;
                    break;
                case 4:
                    Level = 120;
                    Reborns = 0;
                    break;
                case 5:
                    Level = 90;
                    Reborns = 0;
                    break;
                case 6:
                    Level = 110;
                    Reborns = 0;
                    break;
                case 7:
                    Level = 120;
                    Reborns = 0;
                    break;
                case 8:
                    Level = 120;
                    Reborns = 0;
                    break;
                case 9:
                    Level = 120;
                    Reborns = 0;
                    break;
            }

            #endregion

            if (Sc.Level > Sc.Phase && Entity.Level >= Level && Entity.Reborn >= Reborns)
                Pass = true;

            if (Sc is { Level: 9, Phase: 9 })
                Pass = false;

            return Pass;
        }

