        private static void SendChiRankings(GenericRanking ranking, GameState client) {
            SendRankingQuery(ranking, client, GenericRanking.DragonChi, (uint)client.ChiData.DragonRank,
                (uint)client.ChiData.DragonPoints);
            SendRankingQuery(ranking, client, GenericRanking.PhoenixChi, (uint)client.ChiData.PhoenixRank,
                (uint)client.ChiData.PhoenixPoints);
            SendRankingQuery(ranking, client, GenericRanking.TigerChi, (uint)client.ChiData.TigerRank,
                (uint)client.ChiData.TigerPoints);
            SendRankingQuery(ranking, client, GenericRanking.TurtleChi, (uint)client.ChiData.TurtleRank,
                (uint)client.ChiData.TurtlePoints);
        }

        public static void SendRankingQuery(GenericRanking ranking, GameState client, uint type, uint rank,
            uint points) {
            if (rank != 0) {
                ranking.RankingType = type;
                ranking.Append(rank, points, client.Entity.UID, client.Entity.Name);
                client.Send(ranking);
                ranking.Reset();
            }
        }

        private static bool PassJoinRequirements(GameState client, Guild guild) {
            var cmd = new GuildCommand(true) {
                Type = GuildCommand.GuildRequirements,
                dwParam2 = guild.LevelRequirement,
                dwParam3 = guild.RebornRequirement,
                dwParam4 = guild.ClassRequirement
            };
            if ((client.Entity.Class is >= 10 and <= 15 && !guild.AllowTrojans) ||
                (client.Entity.Class is >= 20 and <= 25 && !guild.AllowWarriors) ||
                (client.Entity.Class is >= 40 and <= 45 && !guild.AllowArchers) ||
                (client.Entity.Class is >= 50 and <= 55 && !guild.AllowNinjas) ||
                (client.Entity.Class is >= 60 and <= 65 && !guild.AllowMonks) ||
                (client.Entity.Class is >= 70 and <= 75 && !guild.AllowPirates) ||
                (client.Entity.Class is >= 100 and <= 190 && !guild.AllowTaoists) ||
                client.Entity.Reborn < guild.RebornRequirement || client.Entity.Level < guild.LevelRequirement) {
                client.Send(cmd);
                return false;
            }

            return true;
        }

        private static bool SwitchEquipment(GameState client, bool toAlternative) {
            if (client.Entity.ContainsFlag(Update.Flags.Fly)) {
                client.Send(new Message("You cannot switch equipment during flight.", Color.Red, Message.Talk));
                return false;
            }

            if (client.Equipment.Free(ConquerItem.AlternateRightWeapon) &&
                !client.Equipment.Free(ConquerItem.AlternateLeftWeapon)) {
                client.Send(new Message(
                    "Invalid weapons! Missing the important weapons? Unequip the alternative left weapon.", Color.Red,
                    Message.Talk));
                return false;
            }

            foreach (var eq in client.Equipment.Objects) {
                if (eq != null) {
                    if (!ConquerItemInformation.BaseInformations.ContainsKey(eq.ID)) {
                        //Database.ConquerItemTable.backupAddItem(eq, client);
                        client.Send(new Message(
                            "You cannot switch equipment because " +
                            ((Enums.ItemPositionName)eq.Position).ToString().Replace("_", "~") + "'" +
                            ((eq.Position % 20) == ConquerItem.Boots ? "" : "s") +
                            " stats are not compatible with you (level or profession).", "SYSTEM", Color.Red,
                            Message.Talk));
                        return false;
                    }

                    var itemInfo = ConquerItemInformation.BaseInformations[eq.ID];
                    if (!((EquipPassLvlReq(itemInfo, client) || EquipPassRbReq(itemInfo, client)) &&
                          EquipPassJobReq(itemInfo, client))) {
                        client.Send(new Message(
                            "You cannot switch equipment because " +
                            ((Enums.ItemPositionName)eq.Position).ToString().Replace("_", "~") + "'" +
                            (string)((eq.Position % 20) == ConquerItem.Boots ? "" : "s") +
                            " stats are not compatible with you (level or profession).", "SYSTEM", Color.Red,
                            Message.Talk));
                        return false;
                    }
                }
            }

            client.Entity.AttackPacket = null;
            client.Entity.RemoveFlag(Update.Flags.Fly);
            client.AlternateEquipment = toAlternative;
            client.LoadItemStats();
            client.Equipment.UpdateEntityPacket();
            return true;
        }

