        #region CreateTeam

        public static void CreateTeam(Team team, GameState client) {
            if (client.Entity.MaxHitpoints == 0) //if(hp == 0) the client will close
                return;
            if (client.Entity.MapID == 8892 || client.InQualifier()) {
                var reply = new NpcReply(6, "Sorry, All team Systems is forbidden here") {
                    OptionID = 255
                };
                client.Send(reply.ToArray());
                return;
            }

            client.Team = new Game.ConquerStructures.Team(client);

            team.Type = 15;
            client.Send(team.ToArray());

            team.Type = 0;
            client.Send(team.ToArray());
            return;
        }

        #endregion

        private static bool NulledClient(GameState client) {
            return client is null or { Entity: null };
        }

        internal static bool IsShield(uint p) {
            return p / 1000 == 900;
        }

        internal static bool IsBow(uint p) {
            return p / 1000 == 500;
        }

