        #region TradePartners

        static void RequestTradePartnership(TradePartner partner, GameState client) {
            if (client.Screen.Contains(partner.UID)) {
                var Client = Kernel.GamePool[partner.UID];
                if (Client != null) {
                    if (Client.TradePartnerRequest != client.Entity.UID) {
                        client.TradePartnerRequest = Client.Entity.UID;
                        partner.UID = client.Entity.UID;
                        partner.Name = client.Entity.Name;
                        Client.Send(partner);
                    }
                    else {
                        var Now = DateTime.Now;
                        client.Partners.Add(Client.Entity.UID, new Game.ConquerStructures.Society.TradePartner() {
                            ID = Client.Entity.UID,
                            Name = Client.Entity.Name,
                            ProbationStartedOn = Now
                        });
                        Client.Partners.Add(client.Entity.UID, new Game.ConquerStructures.Society.TradePartner() {
                            ID = Client.Entity.UID,
                            Name = Client.Entity.Name,
                            ProbationStartedOn = Now
                        });
                        client.Send(new TradePartner(true) {
                            UID = Client.Entity.UID,
                            Type = TradePartner.AddPartner,
                            Name = Client.Entity.Name,
                            HoursLeft = (int)(new TimeSpan(Now.AddDays(3).Ticks).TotalHours -
                                              new TimeSpan(Now.Ticks).TotalHours),
                            Online = true
                        });
                        Client.Send(new TradePartner(true) {
                            UID = client.Entity.UID,
                            Type = TradePartner.AddPartner,
                            Name = client.Entity.Name,
                            HoursLeft = (int)(new TimeSpan(Now.AddDays(3).Ticks).TotalHours -
                                              new TimeSpan(Now.Ticks).TotalHours),
                            Online = true
                        });
                        Database.KnownPersons.AddPartner(client, client.Partners[Client.Entity.UID]);
                        client.SendScreen(
                            new Message(
                                Client.Entity.Name + " has begun " + client.Entity.Name +
                                " a partnership probation for three days!", Color.Red, Message.TopLeft));
                    }
                }
            }
        }

        static void RejectPartnership(TradePartner partner, GameState client) {
            client.TradePartnerRequest = 0;
            var Client = Kernel.GamePool[partner.UID];
            if (Client != null) {
                Client.Send(new TradePartner(true) {
                    UID = client.Entity.UID,
                    Type = TradePartner.RejectRequest,
                    Name = client.Entity.Name,
                    Online = true
                });
            }
        }

        static void BreakPartnership(TradePartner partner, GameState client) {
            if (client.Partners.ContainsKey(partner.UID)) {
                if (Kernel.GamePool.TryGetValue(partner.UID, out var Client)) {
                    Client.Partners.Remove(client.Entity.UID);
                    Client.Send(new TradePartner(true) {
                        UID = client.Entity.UID,
                        Type = TradePartner.BreakPartnership,
                        Name = "",
                        Online = false
                    });
                    Client.Send(new Message(client.Entity.Name + " has broken the partnership with you.", Color.Red,
                        Message.TopLeft));

                    client.Send(new TradePartner(true) {
                        UID = partner.UID,
                        Type = TradePartner.BreakPartnership,
                        Name = "",
                        Online = false
                    });
                    client.Partners.Remove(partner.UID);
                    Database.KnownPersons.RemovePartner(client, partner.UID);
                    Client.Send(new Message("You have broken the partnership with " + partner.Name + ".", Color.Red,
                        Message.TopLeft));
                }
            }
        }

