        static void ComposePlus(Compose compose, GameState client) {
            ConquerItem[] Minors = null;
            if (client.Inventory.TryGetItem(compose[0], out var Item) ||
                (client.Equipment.TryGetItem(compose[0]) != null) || (compose.Mode == Compose.QuickCompose)) {
                if (Item == null && !client.Inventory.TryGetItem(compose[0], out Item) &&
                    (client.Equipment.TryGetItem(compose[0]) != null))
                    Item = client.Equipment.TryGetItem(compose[0]);

                if (compose.Mode is Compose.DragonBallUpgrade or Compose.MeteorUpgrade) {
                    Minors = new ConquerItem[compose.Countx];
                    for (var i = 0; i < compose.Countx; i++) {
                        if (!client.Inventory.TryGetItem(compose[i + 2], out Minors[i]))
                            return;
                        else if (Minors[i].UID == Item.UID)
                            return;
                    }
                }
                else {
                    Minors = new ConquerItem[compose.Count - 1];
                    for (var i = 0; i < compose.Count - 1; i++) {
                        if (!client.Inventory.TryGetItem(compose[i + 1], out Minors[i]))
                            return;
                        else if (Minors[i].UID == Item.UID)
                            return;
                    }
                }

                var pos = ItemPosition(Item.ID);
                if (pos is ConquerItem.Bottle or ConquerItem.Garment or ConquerItem.LeftWeaponAccessory
                    or ConquerItem.RightWeaponAccessory or ConquerItem.SteedArmor) //mohsen.. i'm remove crop
                    return;

                if (compose.Mode is Compose.ChanceUpgrade or Compose.QuickCompose) {
                    if (Item is { Plus: < 12, PlusProgress: not 0 }) {
                        var percent = Item.PlusProgress / (double)DataHolder.ComposePlusPoints(Item.Plus);
                        if (Kernel.Rate(percent)) {
                            Item.PlusProgress = 0;
                            Item.Plus++;
                        }
                        else
                            Item.PlusProgress = 0;

                        Item.Mode = Enums.ItemMode.Update;
                        Item.Send(client);
                        ConquerItemTable.UpdatePlus(Item);
                        ConquerItemTable.UpdatePlusProgress(Item);
                        if (Item.Plus >= 9)
                            Kernel.SendWorldMessage(
                                new Message(
                                    "Congratulations, " + client.Entity.Name + " has upgraded His " +
                                    ConquerItemInformation.BaseInformations[Item.ID].Name + " to + " + Item.Plus +
                                    " and " + Item.PlusProgress + " in Progress!", Color.Red, Message.TopLeft),
                                Program.Values);
                    }

                    return;
                }

                if (compose.Mode is Compose.MeteorUpgrade or Compose.DragonBallUpgrade) {
                    var info = new ConquerItemInformation(Item.ID, Item.Plus);

                    Minors = new ConquerItem[compose.Count - 2];
                    for (var i = 0; i < compose.Count - 2; i++) {
                        if (!client.Inventory.TryGetItem(compose[i + 2], out Minors[i]))
                            return;
                        else if (Minors[i].UID == Item.UID)
                            return;
                    }

                    switch (compose.Mode) {
                        case Compose.DragonBallUpgrade: {
                            if (Item.ID % 10 == (byte)Enums.ItemQuality.Super)
                                break;
                            if (Item.Durability < Item.MaximDurability)
                                break;
                            // byte chance = (byte)(70 - ((infos.BaseInformation.Level - (infos.BaseInformation.Level > 100 ? 30 : 0)) / (10 - Item.ID % 10)));
                            var cost = DragonBallUpgradeCost(Item, info);
                            var chance = ((compose.Countx / (double)cost) * 100);
                            if (MyMath.Success(chance)) {
                                switch ((Enums.ItemQuality)(Item.ID % 10)) {
                                    case Enums.ItemQuality.Normal:
                                    case Enums.ItemQuality.NormalV1:
                                    case Enums.ItemQuality.NormalV2:
                                    case Enums.ItemQuality.NormalV3:
                                        Item.ID = (Item.ID - (Item.ID % 10)) + (byte)Enums.ItemQuality.Refined; break;
                                    default: Item.ID++; break;
                                }

                                ConquerItemTable.UpdateItemID(Item, client);
                                Item.Mode = Enums.ItemMode.Update;
                                Item.Send(client);
                                client.Send(new ItemUsage(true) {
                                    UID = client.Entity.UID,
                                    dwParam = 1,
                                    ID = ItemUsage.DragonBallUpgrade
                                });
                            }
                            else {
                                Item.Durability = (ushort)(Item.Durability / 2);
                                ConquerItemTable.UpdateDurabilityItem(Item);
                                Item.Mode = Enums.ItemMode.Update;
                                Item.Send(client);
                            }

                            foreach (var item in Minors)
                                client.Inventory.Remove(item, Enums.ItemUse.Remove);
                            if (compose.Countx > cost) {
                                var diff = compose.Countx - cost;
                                client.Inventory.Add(Minors[0].ID == 720028 ? DragonBall : 1088001, 0,
                                    (byte)diff);
                            }

                            break;
                        }
                        case Compose.MeteorUpgrade: {
                            if (info.BaseInformation.Level == ItemMaxLevel(ItemPosition(info.BaseInformation.ID)))
                                break;
                            if (Item.Durability < Item.MaximDurability) {
                                client.MessageBox("Ro7 sal7ha ya Dog ..");
                                break;
                            }

                            var cost = MeteorUpgradeCost(Item.ID);
                            if (ItemPosition(Item.ID) == ConquerItem.Armor ||
                                ItemPosition(Item.ID) == ConquerItem.Head || IsShield(Item.ID)) {
                                if (info.BaseInformation.Level >= 110)
                                    cost = 1;
                            }
                            else {
                                if (info.BaseInformation.Level >= 115)
                                    cost = 1;
                            }

                            var chance = ((compose.Countx / (double)cost) * 100);
                            var newid = info.CalculateUplevel();
                            if (newid != 0 && newid != Item.ID) {
                                if (MyMath.Success(chance)) {
                                    Item.ID = newid;
                                    info = new ConquerItemInformation(Item.ID, Item.Plus);
                                    Item.Durability = Item.MaximDurability = info.BaseInformation.Durability;
                                    ConquerItemTable.UpdateItemID(Item, client);
                                    ConquerItemTable.UpdateDurabilityItem(Item);
                                    Item.Mode = Enums.ItemMode.Update;
                                    Item.Send(client);

                                    client.Send(new ItemUsage(true) {
                                        UID = client.Entity.UID,
                                        dwParam = 1,
                                        ID = ItemUsage.MeteorUpgrade
                                    });
                                }
                                else {
                                    Item.Durability = (ushort)(Item.Durability / 2);
                                    ConquerItemTable.UpdateDurabilityItem(Item);
                                    Item.Mode = Enums.ItemMode.Update;
                                    Item.Send(client);
                                }
                            }

                            foreach (var item in Minors)
                                client.Inventory.Remove(item, Enums.ItemUse.Remove);
                            if (compose.Countx > cost) {
                                var diff = compose.Countx - cost;
                                client.Inventory.Add(Minors[0].ID == 720028 ? DragonBall : 1088001, 0,
                                    (byte)diff);
                            }

                            break;
                        }
                    }
                }

                foreach (var item in Minors) {
                    var ItemPlus = item;
                    var infos = new ConquerItemInformation(Item.ID, Item.Plus);
                    switch (compose.Mode) {
                        case Compose.CurrentSteed:
                        case Compose.Plus: {
                            if (Item.Plus < 12 && Item.GetItemType() != ConquerItem.ItemTypes.GarmentID_1 &&
                                Item.GetItemType() != ConquerItem.ItemTypes.GarmentID_2 &&
                                Item.GetItemType() != ConquerItem.ItemTypes.BottleID &&
                                Item.GetItemType() != ConquerItem.ItemTypes.RightAccessory1 &&
                                Item.GetItemType() != ConquerItem.ItemTypes.RightAccessory2 &&
                                Item.GetItemType() != ConquerItem.ItemTypes.RightAccessory3 &&
                                Item.GetItemType() != ConquerItem.ItemTypes.LeftAccessory) {
                                Item.PlusProgress += DataHolder.StonePlusPoints(ItemPlus.Plus);
                                while (Item.PlusProgress >= DataHolder.ComposePlusPoints(Item.Plus) &&
                                       Item.Plus != 12) {
                                    Item.PlusProgress -= DataHolder.ComposePlusPoints(Item.Plus);
                                    Item.Plus++;
                                    if (Item.Plus == 12)
                                        Item.PlusProgress = 0;
                                }

                                Item.Mode = Enums.ItemMode.Update;
                                Item.Send(client);
                                ConquerItemTable.UpdatePlus(Item);
                                ConquerItemTable.UpdatePlusProgress(Item);
                                client.Inventory.Remove(ItemPlus, Enums.ItemUse.Remove);
                                if (Item.Plus >= 9)
                                    Kernel.SendWorldMessage(
                                        new Message(
                                            "Congratulations, " + client.Entity.Name + " has upgraded His " +
                                            ConquerItemInformation.BaseInformations[Item.ID].Name + " to + " +
                                            Item.Plus + " and " + Item.PlusProgress + " in Progress!", Color.Red,
                                            Message.TopLeft), Program.Values);
                            }

                            break;
                        }
                        case Compose.NewSteed: {
                            if (Item.Plus < 12) {
                                Item.PlusProgress += DataHolder.StonePlusPoints(ItemPlus.Plus);
                                while (Item.PlusProgress >= DataHolder.ComposePlusPoints(Item.Plus) &&
                                       Item.Plus != 12) {
                                    Item.PlusProgress -= DataHolder.ComposePlusPoints(Item.Plus);
                                    Item.Plus++;
                                    if (Item.Plus == 12)
                                        Item.PlusProgress = 0;
                                }

                                Item.Mode = Enums.ItemMode.Update;
                                Item.Send(client);
                                ConquerItemTable.UpdatePlus(Item);
                                client.Inventory.Remove(ItemPlus, Enums.ItemUse.Remove);
                            }

                            var color1 = (int)Item.SocketProgress;
                            var color2 = (int)ItemPlus.SocketProgress;

                            var G1 = color1 & 0xFF;
                            var G2 = color2 & 0xFF;
                            var B1 = (color1 >> 8) & 0xFF;
                            var B2 = (color2 >> 8) & 0xFF;
                            var R1 = (color1 >> 16) & 0xFF;
                            var R2 = (color2 >> 16) & 0xFF;
                            Item.NextGreen = (byte)((int)Math.Floor(0.9 * G1) + (int)Math.Floor(0.1 * G2) + 1);
                            Item.NextBlue = (byte)((int)Math.Floor(0.9 * B1) + (int)Math.Floor(0.1 * B2) + 1);
                            Item.NextRed = (byte)((int)Math.Floor(0.9 * R1) + (int)Math.Floor(0.1 * R2) + 1);
                            Item.SocketProgress = (uint)(Item.NextGreen | (Item.NextBlue << 8) | (Item.NextRed << 16));

                            Item.Mode = Enums.ItemMode.Update;
                            Item.Send(client);
                            ConquerItemTable.UpdatePlusProgress(Item);
                            ConquerItemTable.UpdateSocketProgress(Item);
                            //  Database.ConquerItemTable.UpdateNextSteedColor(Item);
                            client.Inventory.Remove(ItemPlus, Enums.ItemUse.Remove);
                            break;
                        }
                    }
                }
            }
        }


        static byte DragonBallUpgradeCost(ConquerItem Item, ConquerItemInformation info) {
            var change = 100;
            switch (Item.ID % 10) {
                case 6: change = 50; break;
                case 7: change = 33; break;
                case 8: change = 20; break;
                default: change = 100; break;
            }

            int level = info.BaseInformation.Level;
            if (level > 70)
                change = (int)(change * (100 - (level - 70) * 1.0) / 100);
            return (byte)(100 / change + 1);
        }

        public static byte GetLevel(uint ID) {
            if (ItemPosition(ID) == ConquerItem.Armor || ItemPosition(ID) == ConquerItem.Head ||
                IsShield(ID))
                return (byte)((ID % 100) / 10);
            else
                return (byte)((ID % 1000) / 10);
        }

        public static byte MeteorUpgradeCost(uint ID) {
            var wQuality = (int)(ID % 10);
            var nLevel = GetLevel(ID);
            switch (wQuality) {
                case 9: {
                    if (ItemPosition(ID) == ConquerItem.Armor || ItemPosition(ID) == ConquerItem.Head ||
                        IsShield(ID)) {
                        if (nLevel <= 4) return 3;
                        if (nLevel == 5) return 25;
                        if (nLevel == 6) return 31;
                        if (nLevel == 7) return 40;
                        if (nLevel > 7) return 61;
                    }
                    else {
                        if (nLevel <= 10)
                            return 3;
                        else if (nLevel <= 12)
                            return 14;
                        else if (nLevel <= 14)
                            return 15;
                        else if (nLevel <= 16)
                            return 18;
                        else if (nLevel <= 18)
                            return 20;
                        else if (nLevel <= 20)
                            return 25;
                        else
                            return 31;
                    }

                    break;
                }
                case 8: {
                    if (ItemPosition(ID) == ConquerItem.Armor || ItemPosition(ID) == ConquerItem.Head ||
                        IsShield(ID)) {
                        if (nLevel <= 4) return 2;
                        if (nLevel == 5) return 8;
                        if (nLevel == 6) return 10;
                        if (nLevel == 7) return 14;
                        if (nLevel > 7) return 20;
                    }
                    else {
                        if (nLevel <= 10)
                            return 2;
                        else if (nLevel <= 12)
                            return 4;
                        else if (nLevel <= 16)
                            return 6;
                        else if (nLevel <= 18)
                            return 7;
                        else if (nLevel <= 20)
                            return 8;
                        else
                            return 9;
                    }

                    break;
                }
                case 7: {
                    if (ItemPosition(ID) == ConquerItem.Armor || ItemPosition(ID) == ConquerItem.Head ||
                        IsShield(ID)) {
                        if (nLevel <= 4) return 2;
                        if (nLevel is > 4 and < 6) return 3;
                        if (nLevel == 6) return 4;
                        if (nLevel == 7) return 6;
                        if (nLevel > 7) return 9;
                    }
                    else {
                        if (nLevel <= 15)
                            return 2;
                        else if (nLevel <= 20)
                            return 3;
                        else
                            return 4;
                    }

                    break;
                }
                case 6: {
                    if (ItemPosition(ID) == ConquerItem.Armor || ItemPosition(ID) == ConquerItem.Head ||
                        IsShield(ID)) {
                        if (nLevel <= 4) return 2;
                        if (nLevel is > 4 and < 7) return 3;
                        if (nLevel == 7) return 4;
                        if (nLevel > 7) return 7;
                    }
                    else {
                        if (nLevel <= 18)
                            return 2;
                        else
                            return 3;
                    }

                    break;
                }
                default: {
                    if (ItemPosition(ID) == ConquerItem.Armor || ItemPosition(ID) == ConquerItem.Head ||
                        IsShield(ID)) {
                        if (nLevel <= 4) return 2;
                        if (nLevel is > 4 and < 7) return 3;
                        if (nLevel == 7) return 4;
                        if (nLevel > 7) return 7;
                    }
                    else {
                        if (nLevel <= 19)
                            return 2;
                        else
                            return 3;
                    }

                    break;
                }
            }

            return 0;
        }

        #endregion a7a low etshal tany b2a

        static void SocketItem(ItemUsage usage, GameState client) {
            if (client.Inventory.TryGetItem(usage.UID, out var item)) {
                var pos = ItemPosition(item.ID);
                if (pos is ConquerItem.Bottle or ConquerItem.Fan or ConquerItem.Garment
                    or ConquerItem.LeftWeaponAccessory or ConquerItem.RightWeaponAccessory or ConquerItem.Steed
                    or ConquerItem.SteedArmor or ConquerItem.SteedCrop or ConquerItem.Tower or ConquerItem.Wing) {
                    client.Send(new Message("Sorry can't make socket in this item !", Color.Red, Message.Talk));
                    return;
                }

                var Minors = new ConquerItem[usage.Batch.Length];
                for (var i = 0; i < usage.Batch.Length; i++) {
                    if (!client.Inventory.TryGetItem(usage.Batch[i], out Minors[i]))
                        return;
                    else if (Minors[i].UID == item.UID)
                        return;
                }

                if (Minors.Length == 0)
                    return;
                if (item.SocketOne == Enums.Gem.NoSocket) {
                    ushort cost = 1;
                    if (pos is not ConquerItem.RightWeapon and not ConquerItem.LeftWeapon)
                        cost = 12;

                    if (client.Inventory.Contains(DragonBall, cost)) {
                        item.SocketOne = Enums.Gem.EmptySocket;
                        item.Mode = Enums.ItemMode.Update;
                        item.Send(client);
                        usage.dwParam = 1;
                        client.LoadItemStats();
                        ConquerItemTable.UpdateSockets(item);
                        foreach (var xitem in Minors) {
                            client.Inventory.Remove(xitem.UID, Enums.ItemUse.Remove, true);
                        }
                    }
                }
                else if (item.SocketTwo == Enums.Gem.NoSocket) {
                    ushort cost = 5;
                    if (pos is not ConquerItem.RightWeapon and not ConquerItem.LeftWeapon) {
                        cost = 1;
                        var minor = Minors.FirstOrDefault();
                        if (minor.ID == 1200005) {
                            if (client.Inventory.Contains(1200005, cost)) {
                                if (Kernel.Rate((double)30)) {
                                    item.SocketTwo = Enums.Gem.EmptySocket;
                                    item.Mode = Enums.ItemMode.Update;
                                    item.Send(client);
                                    usage.dwParam = 1;
                                    client.LoadItemStats();
                                    ConquerItemTable.UpdateSockets(item);
                                }
                                else {
                                    usage.dwParam = 0;
                                    client.Inventory.Add(1200006, 0, 1);
                                }

                                foreach (var xitem in Minors) {
                                    client.Inventory.Remove(xitem.UID, Enums.ItemUse.Remove, true);
                                }
                            }
                        }
                        else if (minor.ID == 1200006) {
                            cost = 7;
                            if (client.Inventory.Contains(1200006, cost)) {
                                item.SocketTwo = Enums.Gem.EmptySocket;
                                item.Mode = Enums.ItemMode.Update;
                                item.Send(client);
                                usage.dwParam = 1;
                                client.LoadItemStats();
                                ConquerItemTable.UpdateSockets(item);
                                foreach (var xitem in Minors) {
                                    client.Inventory.Remove(xitem.UID, Enums.ItemUse.Remove, true);
                                }
                            }
                        }
                    }
                    else {
                        if (client.Inventory.Contains(DragonBall, cost)) {
                            item.SocketTwo = Enums.Gem.EmptySocket;
                            item.Mode = Enums.ItemMode.Update;
                            item.Send(client);
                            usage.dwParam = 1;
                            client.LoadItemStats();
                            ConquerItemTable.UpdateSockets(item);
                            foreach (var xitem in Minors) {
                                client.Inventory.Remove(xitem.UID, Enums.ItemUse.Remove, true);
                            }
                        }
                    }
                }
            }
        }

        static void SocketItem(EmbedSocket socket, GameState client) {
            if (client.Inventory.TryGetItem(socket.ItemUID, out var Item) ||
                (client.Equipment.TryGetItem(socket.ItemUID) != null)) {
                if (Item == null && !client.Inventory.TryGetItem(socket.ItemUID, out Item) &&
                    (client.Equipment.TryGetItem(socket.ItemUID) != null))
                    Item = client.Equipment.TryGetItem(socket.ItemUID);
                var sock = ItemPosition(Item.ID);
                if (sock is 7 or 9 or > 19) {
                    client.Send(new Message("Sorry can't make socket in this item !", Color.Red, Message.Talk));
                    return;
                }

                if (client.Inventory.TryGetItem(socket.GemUID, out var Gem) || socket.Mode == EmbedSocket.Remove) {
                    switch (socket.Mode) {
                        case EmbedSocket.Add: {
                            var gemBase = (byte)(Gem.ID % 1000);

                            #region No ONecan make un allowedgem in Talisman

                            if (sock == (ushort)Positions.AttackTalisman) {
                                if (!(gemBase is >= (byte)Enums.Gem.NormalThunderGem
                                        and <= (byte)Enums.Gem.SuperThunderGem)) {
                                    client.Send(new Message("Sorry can't make socket in this item !", Color.Red,
                                        Message.Talk));
                                    return;
                                }
                            }

                            if (sock == (ushort)Positions.DefenceTalisman) {
                                if (!(gemBase is >= (byte)Enums.Gem.NormalGloryGem
                                        and <= (byte)Enums.Gem.SuperGloryGem)) {
                                    client.Send(new Message("Sorry can't make socket in this item !", Color.Red,
                                        Message.Talk));
                                    return;
                                }
                            }

                            #endregion No ONecan make un allowedgem in Talisman

                            if (Enum.IsDefined(typeof(Enums.Gem), gemBase)) {
                                switch (socket.Slot) {
                                    case EmbedSocket.SlotOne: {
                                        if ((byte)Item.SocketOne == 255) {
                                            Item.SocketOne = (Enums.Gem)(Gem.ID % 1000);
                                            Item.Mode = Enums.ItemMode.Update;
                                            Item.Send(client);
                                            ConquerItemTable.UpdateSockets(Item);
                                            client.Inventory.Remove(Gem, Enums.ItemUse.RemoveFromStack);
                                            break;
                                        }

                                        break;
                                    }
                                    case EmbedSocket.SlotTwo: {
                                        if ((byte)Item.SocketOne > 0 && (byte)Item.SocketOne < 255) {
                                            if ((byte)Item.SocketTwo == 255) {
                                                Item.SocketTwo = (Enums.Gem)(Gem.ID % 1000);
                                                Item.Mode = Enums.ItemMode.Update;
                                                Item.Send(client);
                                                ConquerItemTable.UpdateSockets(Item);
                                                client.Inventory.Remove(Gem, Enums.ItemUse.RemoveFromStack);
                                            }
                                        }
                                        else if ((byte)Item.SocketOne == 255) {
                                            Item.SocketOne = (Enums.Gem)(Gem.ID % 1000);
                                            Item.Mode = Enums.ItemMode.Update;
                                            Item.Send(client);
                                            ConquerItemTable.UpdateSockets(Item);
                                            client.Inventory.Remove(Gem, Enums.ItemUse.RemoveFromStack);
                                        }

                                        break;
                                    }
                                }
                            }

                            break;
                        }
                        case EmbedSocket.Remove: {
                            switch (socket.Slot) {
                                case EmbedSocket.SlotOne: {
                                    if ((byte)Item.SocketOne != 0) {
                                        Item.SocketOne = Enums.Gem.EmptySocket;
                                        if ((byte)Item.SocketTwo != 0 && (byte)Item.SocketTwo != 255) {
                                            Item.SocketOne = Item.SocketTwo;
                                            Item.SocketTwo = Enums.Gem.EmptySocket;
                                        }

                                        Item.Mode = Enums.ItemMode.Update;
                                        Item.Send(client);
                                        ConquerItemTable.UpdateSockets(Item);
                                        break;
                                    }

                                    break;
                                }
                                case EmbedSocket.SlotTwo: {
                                    if ((byte)Item.SocketTwo != 0 && (byte)Item.SocketTwo != 255) {
                                        Item.SocketTwo = Enums.Gem.EmptySocket;
                                        Item.Mode = Enums.ItemMode.Update;
                                        Item.Send(client);
                                        ConquerItemTable.UpdateSockets(Item);
                                    }
                                    else {
                                        if ((byte)Item.SocketOne != 0) {
                                            Item.SocketOne = Enums.Gem.EmptySocket;
                                            Item.Mode = Enums.ItemMode.Update;
                                            Item.Send(client);
                                            ConquerItemTable.UpdateSockets(Item);
                                        }
                                    }

                                    break;
                                }
                            }

                            break;
                        }
                    }
                }

                client.Send(socket);
                Thread.Sleep(500);
            }
        }

        static void LockItem(ItemLock itemLock, GameState client) {
            if (client.Inventory.TryGetItem(itemLock.UID, out var item)) {
                itemLock.ID = 1;
                item.Lock = 1;
                item.Mode = Enums.ItemMode.Update;
                client.Send(itemLock);
                item.Send(client);
                ConquerItemTable.UpdateLock(item);
            }
            else if (client.Equipment.TryGetItem(itemLock.UID) != null) {
                item = client.Equipment.TryGetItem(itemLock.UID);
                itemLock.ID = 1;
                item.Lock = 1;
                item.Mode = Enums.ItemMode.Update;
                client.Send(itemLock);
                item.Send(client);
                ConquerItemTable.UpdateLock(item);
            }
        }

        static void UnlockItemInstant(ItemLock itemLock, GameState client) {
            if (client.Inventory.TryGetItem(itemLock.UID, out var item)) {
                if (item.Lock == 1) {
                    item.Lock = 0;
                    item.Mode = Enums.ItemMode.Update;
                    item.Send(client);
                    ConquerItemTable.UpdateLock(item);
                }
                else
                    client.Send(new Message("Can't unlock an item that is in progress of unlocking.", Color.FloralWhite,
                        Message.TopLeft));
            }
        }

        static void UnlockItem5Days(ItemLock itemLock, GameState client) {
            if (client.Inventory.TryGetItem(itemLock.UID, out var item)) {
                if (item.Lock == 1) {
                    item.Lock = 2;
                    item.UnlockEnd = DateTime.Now.AddDays(5);
                    item.Mode = Enums.ItemMode.Update;
                    item.Send(client);
                    ConquerItemTable.UpdateLock(item);
                }
                else
                    client.Send(new Message("Can't unlock an item that is in progress of unlocking.", Color.FloralWhite,
                        Message.TopLeft));
            }
        }

        static void SocketTalismanWithItem(ItemUsage itemUsage, GameState client) {
            var talisman = client.Equipment.TryGetItem(itemUsage.UID);
            for (ushort i = 91; i < 91 + 4 * itemUsage.ToArray()[26]; i += 4) {
                var item_swap = BitConverter.ToUInt32(itemUsage.ToArray(), i);

                if (client.Inventory.TryGetItem(item_swap, out var item)) {
                    if (talisman == null)
                        return;
                    if (item.ID / 1000 == talisman.ID / 1000)
                        return;
                    if (item.Bound)
                        return;
                    if (talisman.SocketTwo != Enums.Gem.NoSocket)
                        return;

                    ushort Points = 0;
                    switch (item.ID % 10) {
                        case 6: Points += 5; break;
                        case 7: Points += 10; break;
                        case 8: Points += 40; break;
                        case 9: Points += 1000; break;
                    }

                    Points += DataHolder.TalismanPlusPoints(item.Plus);

                    int position = ItemPosition(item.ID);
                    switch (position) {
                        case 0: return;
                        case 4:
                        case 5:
                            if (item.ID % 10 >= 8) {
                                if (item.SocketOne != Enums.Gem.NoSocket)
                                    Points += 160;
                                if (item.SocketTwo != Enums.Gem.NoSocket)
                                    Points += 800;
                            }

                            break;
                        default:
                            if (item.ID % 10 >= 8) {
                                if (item.SocketOne != Enums.Gem.NoSocket)
                                    Points += 2000;
                                if (item.SocketTwo != Enums.Gem.NoSocket)
                                    Points += 6000;
                            }

                            break;
                    }

                    talisman.SocketProgress += Points;
                    if (talisman is { SocketOne: Enums.Gem.NoSocket, SocketProgress: >= 8000 }) {
                        talisman.SocketProgress -= 8000;
                        talisman.SocketOne = Enums.Gem.EmptySocket;

                        talisman.Mode = Enums.ItemMode.Update;
                        talisman.Send(client);
                        if (talisman.Position != 0)
                            client.LoadItemStats();
                    }

                    if (talisman.SocketOne != Enums.Gem.NoSocket) {
                        if (talisman.SocketProgress >= 20000) {
                            talisman.SocketProgress = 0;
                            talisman.SocketTwo = Enums.Gem.EmptySocket;
                        }
                    }

                    talisman.Mode = Enums.ItemMode.Update;
                    talisman.Send(client);
                    ConquerItemTable.UpdateSocketProgress(talisman);
                    ConquerItemTable.UpdateSockets(talisman);
                    if (talisman.Position != 0)
                        client.LoadItemStats();
                    client.Inventory.Remove(item, Enums.ItemUse.Remove);
                }
            }
        }

        static void SocketTalismanWithCPs(ItemUsage itemUsage, GameState client) {
            var talisman = client.Equipment.TryGetItem(itemUsage.UID);

            if (talisman == null)
                return;

            var pos = ItemPosition(talisman.ID);
            if (pos is not ConquerItem.Fan and not ConquerItem.Tower and not ConquerItem.Wing)
                return;

            uint price = 0;
            if (talisman.SocketOne == Enums.Gem.NoSocket) {
                double procent = 100 - (talisman.SocketProgress * 25600 / 2048000);
                if (100 - procent < 25)
                    return;
                price = (uint)(procent * 55);
            }
            else if (talisman.SocketTwo == Enums.Gem.NoSocket) {
                double procent = 100 - (talisman.SocketProgress * 25600 / 5120000);
                if (100 - procent < 25)
                    return;
                price = (uint)(procent * 110);
            }
            else
                return;

            if (client.Entity.ConquerPoints >= price) {
                client.Entity.ConquerPoints -= price;
                if (talisman.SocketOne == Enums.Gem.NoSocket)
                    talisman.SocketOne = Enums.Gem.EmptySocket;
                else if (talisman.SocketTwo == Enums.Gem.NoSocket)
                    talisman.SocketTwo = Enums.Gem.EmptySocket;
                talisman.SocketProgress = 0;
                ConquerItemTable.UpdateSockets(talisman);
                talisman.Mode = Enums.ItemMode.Update;
                talisman.Send(client);
            }
        }

        static void EnchantItem(ItemUsage itemUsage, GameState client) {
            if (client.Inventory.TryGetItem(itemUsage.UID, out var Item) &&
                client.Inventory.TryGetItem(itemUsage.dwParam, out var EnchantGem)) {
                var pos = ItemPosition(Item.ID);
                if (pos is ConquerItem.Bottle or ConquerItem.Fan or ConquerItem.Garment
                    or ConquerItem.LeftWeaponAccessory or ConquerItem.RightWeaponAccessory or ConquerItem.Steed
                    or ConquerItem.SteedArmor or ConquerItem.SteedCrop or ConquerItem.Wing or ConquerItem.Tower)
                    return;
                var gemBase = (byte)(EnchantGem.ID % 1000);
                if (Enum.IsDefined(typeof(Enums.Gem), gemBase)) {
                    byte Enchant = 0;
                    switch (EnchantGem.ID % 10) {
                        case 1: {
                            Enchant = (byte)Kernel.Random.Next(1, 59);
                            break;
                        }
                        case 2: {
                            if (EnchantGem.ID == 700012)
                                Enchant = (byte)Kernel.Random.Next(100, 159);
                            else if (EnchantGem.ID is 700002 or 700052 or 700062)
                                Enchant = (byte)Kernel.Random.Next(60, 109);
                            else if (EnchantGem.ID == 700032)
                                Enchant = (byte)Kernel.Random.Next(80, 129);
                            else
                                Enchant = (byte)Kernel.Random.Next(40, 89);
                            break;
                        }
                        default: {
                            if (EnchantGem.ID == 700013)
                                Enchant = (byte)Kernel.Random.Next(200, 255);
                            else if (EnchantGem.ID is 700003 or 700073 or 700033)
                                Enchant = (byte)Kernel.Random.Next(170, 229);
                            else if (EnchantGem.ID is 700063 or 700053)
                                Enchant = (byte)Kernel.Random.Next(140, 199);
                            else if (EnchantGem.ID == 700023)
                                Enchant = (byte)Kernel.Random.Next(90, 149);
                            else
                                Enchant = (byte)Kernel.Random.Next(70, 119);
                            break;
                        }
                    }

                    client.Send(Constants.Enchant(Item.Enchant, Enchant));
                    if (Enchant > Item.Enchant) {
                        Item.Enchant = Enchant;
                        Item.Mode = Enums.ItemMode.Update;
                        Item.Send(client);
                        ConquerItemTable.UpdateEnchant(Item);
                        client.Inventory.Remove(EnchantGem, Enums.ItemUse.Remove);
                    }
                    else {
                        client.Inventory.Remove(EnchantGem, Enums.ItemUse.Remove);
                    }
                }
            }
        }

