        public static void EquipItem(ItemUsage itemUsage, GameState client) {
            client.Entity.AttackPacket = null;
            if (client.Inventory.TryGetItem(itemUsage.UID, out var item) && client.Booth == null) {
                if (item.Suspicious)
                    return;
                if (item.ID / 1000 >= 600) {
                    if (itemUsage.dwParam == 4) {
                        if (!client.Equipment.Free(5)) {
                            if (item.ID / 1000 != client.Equipment.TryGetItem(5).ID / 1000) {
                                return;
                            }
                        }
                    }
                }

                var pos = GetPositionFromID(item.ID);
                if (pos == Positions.Inventory) {
                    UseItem(item, client);
                    return;
                }

                if (ItemPosition(item.ID) == ConquerItem.Garment)
                    if (client.Entity.Tournament_Signed)
                        return;

                #region Sanity checks

                var can2hand = false;
                var can2wpn = false;
                uint dwExtra = 0;
                if (itemUsage.dwParam > 20)
                    dwExtra = 20;
                if (client.Entity.Class is >= 11 and <= 75)
                    can2hand = true;
                if (client.Entity.Class is >= 11 and <= 15 or >= 51 and <= 55 or >= 61 and <= 65 or >= 71 and <= 75)
                    can2wpn = true;
                if (client.Entity.Class is >= 71 and <= 75 or >= 41 and <= 45)
                    can2wpn = true;
                if (client.Entity.Class is >= 20 and <= 25) {
                    can2hand = true;
                    can2wpn = true;
                }

                if (client.Entity.Class is >= 50 and <= 55) {
                    can2hand = true;
                    can2wpn = true;
                }

                if (client.Entity.Class is >= 130 and <= 135 or >= 140 and <= 145) {
                    can2hand = true;
                    can2wpn = true;
                }

                if (client.Entity.Class is >= 80 and <= 85) {
                    can2hand = true;
                    can2wpn = true;
                }

                if (client.Entity.Class is >= 160 and <= 165) {
                    can2hand = true;
                    can2wpn = true;
                }

                //if (client.Entity.Class >= 100)
                //    can2wpn = false;
                if (!Equipable(item, client))
                    return;
                if (ItemPosition(item.ID) == 5) {
                    itemUsage.dwParam = 5 + dwExtra;
                    if (!can2hand && !can2wpn)
                        return;
                    if (client.Equipment.Free(4 + dwExtra) ||
                        (client.Equipment.TryGetItem(4 + dwExtra).ID / 1000 != 500 && IsFranko(item.ID)))
                        return;
                }

                if (ItemPosition(item.ID) == 4) {
                    if (itemUsage.dwParam == 5 + dwExtra)
                        if (!can2hand || !can2wpn)
                            return;
                }

                if (!((itemUsage.dwParam == 4 + dwExtra || itemUsage.dwParam == 5 + dwExtra) &&
                      (ItemPosition(item.ID) == 4 || ItemPosition(item.ID) == 5))) {
                    if (!IsAccessory(item.ID))
                        itemUsage.dwParam = ItemPosition(item.ID) + dwExtra;
                }

                #region Hossu

                if (client.Entity.Class is >= 130 and <= 135 or >= 140 and <= 145) {
                    if ((itemUsage.dwParam - dwExtra) == 5) {
                        if ((item.ID / 1000) == 421 || (item.ID / 1000) == 620)
                            return;
                        var rItem = client.Equipment.TryGetItem((byte)(4 + dwExtra));
                        if (rItem != null) {
                            if (item.ID / 1000 == 619) {
                                if ((rItem.ID / 1000) != 421 && (rItem.ID / 1000) != 620)
                                    return;
                            }
                            else
                                return;
                        }
                    }

                    if ((itemUsage.dwParam - dwExtra) == 4) {
                        var rItem = client.Equipment.TryGetItem((byte)(5 + dwExtra));
                        if (rItem != null) {
                            if (rItem.ID / 1000 == 619) {
                                if ((item.ID / 1000) != 421 && (item.ID / 1000) != 620)
                                    return;
                            }
                        }
                    }
                }

                #endregion Hossu

                var twohand = IsTwoHand(item.ID);
                if (!twohand && itemUsage.dwParam == 4 + dwExtra) {
                    if (!client.Equipment.Free((byte)(5 + dwExtra))) {
                        if (client.Inventory.Count < 40) {
                            if (IsFranko(client.Equipment.TryGetItem((byte)(5 + dwExtra)).ID))
                                client.Equipment.Remove((byte)(5 + dwExtra));
                            else {
                                if (client.Equipment.TryGetItem((byte)(4 + dwExtra)) != null) {
                                    if (IsTwoHand(client.Equipment.TryGetItem((byte)(4 + dwExtra)).ID))
                                        client.Equipment.Remove((byte)(4 + dwExtra));
                                }
                            }
                        }
                    }
                }

                if ((itemUsage.dwParam - dwExtra) == 5) {
                    if ((item.ID / 1000) == 421 || IsTwoHand(item.ID))
                        return;
                    var rItem = client.Equipment.TryGetItem((byte)(4 + dwExtra));
                    if (rItem != null) {
                        if (rItem.IsTwoHander()) {
                            if (IsFranko(item.ID)) {
                                if (rItem.ID / 1000 != 500) return;
                            }
                            else {
                                if (IsShield(item.ID)) {
                                    if ((rItem.ID / 1000) == 421) return;
                                    if (!client.Spells.ContainsKey(10311) && client.Entity is
                                            { FirstRebornClass: 25, SecondRebornClass: 25 }) //Perseverance
                                    {
                                        client.Send(new Message(
                                            "You need to know Perseverance (Warrior Pure skill) to be able to wear 2-handed weapon and shield.",
                                            Color.Red, Message.Talk));
                                        return;
                                    }
                                }
                                else if (item.ID / 1000 == 619) {
                                    if ((rItem.ID / 1000) != 421 && (rItem.ID / 1000) != 620)
                                        return;
                                }
                                else
                                    itemUsage.dwParam = 4 + dwExtra;
                            }
                        }
                    }
                }

                if (itemUsage.dwParam == 4 + dwExtra)
                    if (client.Entity.ContainsFlag(Update.Flags.Fly))
                        if (item.ID / 1000 != 500)
                            return;

                if (!(client.Entity.Class is >= 50 and <= 55))
                    if ((item.ID / 1000) == 601)
                        if ((itemUsage.dwParam - dwExtra) == 5)
                            return;

                #endregion

                var itemType = item.ID / 1000;
                if (itemType == 613) {
                    if (client.Entity.Class is >= 70 and <= 75 or >= 60 and <= 65 or >= 10 and <= 15 or >= 50 and <= 55
                        or >= 20 and <= 25 or >= 142 and <= 145 or >= 132 and <= 135) {
                        item.Position = 0;
                        return;
                    }
                }

                if (itemType == 612) {
                    if (client.Entity.Class is >= 60 and <= 65 or >= 10 and <= 15 or >= 50 and <= 55 or >= 20 and <= 25
                        or >= 142 and <= 145 or >= 132 and <= 135) {
                        item.Position = 0;
                        return;
                    }
                }

                if (client.Entity.ContainsFlag3(Update.Flags3.Assassin))
                    if (item.ID / 1000 != 613)
                        return;

                if (client.Map.ID == 1039)
                    client.Entity.AttackPacket = null;

                item.Position = (ushort)itemUsage.dwParam;
                if (ItemPosition(item.ID) == 5 && !IsFranko(item.ID)) {
                    if (IsTwoHand(client.Equipment.TryGetItem((byte)(4 + dwExtra)).ID)) {
                        if (!client.Spells.ContainsKey(10311)) //Perseverance
                        {
                            client.Send(new Message(
                                "You need to know Perseverance (Warrior Pure skill) to be able to wear 2-handed weapon and shield.",
                                Color.Red, Message.Talk));
                            return;
                        }
                    }
                }

                //  uint itemType = item.ID / 1000;
                if (itemType == 421) {
                    //Backsword
                    if (item.Position == 5 + dwExtra) {
                        item.Position = 0;
                        return;
                    }
                }

                if (itemType == 900) {
                    if (!(client.Entity.Class is >= 20 and <= 25)) {
                        item.Position = 0;
                        return;
                    }
                }

                if (itemUsage.dwParam == ConquerItem.RightWeaponAccessory)
                    if (client.WeaponLook > 0)
                        return;
                if (itemUsage.dwParam == ConquerItem.LeftWeaponAccessory)
                    if (client.WeaponLook2 > 0)
                        return;
                //Database.ConquerItemTable.ClearPosition(client.Entity.UID, (byte)itemUsage.dwParam);
                client.Inventory.Remove(item, Enums.ItemUse.Move, true);
                if (client.Equipment.Free((byte)itemUsage.dwParam)) {
                    if (twohand)
                        client.Equipment.Remove((byte)(5 + dwExtra));
                    item.Position = (byte)itemUsage.dwParam;
                    client.Equipment.Add(item);
                    item.Mode = Enums.ItemMode.Update;
                    item.Send(client);
                }
                else {
                    if (twohand)
                        client.Equipment.Remove((byte)(5 + dwExtra));
                    if (IsBow(client.Equipment.TryGetItem((byte)itemUsage.dwParam).ID)) {
                        client.Entity.RemoveFlag(Update.Flags.Fly);
                    }

                    client.Equipment.Remove((byte)itemUsage.dwParam);
                    item.Position = (byte)itemUsage.dwParam;
                    client.Equipment.Add(item);
                }

                var iu = new ItemUsage(true) {
                    ID = 5,
                    UID = itemUsage.UID,
                    dwParam = itemUsage.dwParam
                };
                client.Send(iu);

                client.CalculateStatBonus();
                client.CalculateHPBonus();
                client.LoadItemStats();
                var equips = new ClientEquip();
                equips.DoEquips(client);
                client.Send(equips);

                ConquerItemTable.UpdateLocation(item, client);
                client.Equipment.UpdateEntityPacket();
                if (itemUsage.dwParam == ConquerItem.Armor)
                    if (client.ArmorLook > 0)
                        client.SetNewArmorLook(client.ArmorLook);
                if (itemUsage.dwParam == ConquerItem.Head)
                    if (client.HeadgearLook > 0)
                        client.SetNewHeadgearLook(client.HeadgearLook);
                if (itemUsage.dwParam == ConquerItem.RightWeapon)
                    if (client.WeaponLook > 0)
                        client.SetNewWeaponLook(client.WeaponLook);
                if (itemUsage.dwParam == ConquerItem.LeftWeapon)
                    if (client.WeaponLook2 > 0)
                        client.SetNewWeaponLook2(client.WeaponLook2);
            }
        }

        public static void UnequipItem(ItemUsage usage, GameState client) {
            if (client.Entity.ContainsFlag3(Update.Flags3.Assassin))
                if (usage.dwParam == 4)
                    return;
            if (!client.Equipment.Free((byte)usage.dwParam))
                if (ItemPosition(client.Equipment.TryGetItem((byte)usage.dwParam).ID) == ConquerItem.Garment)
                    if (ItemPosition(client.Equipment.TryGetItem((byte)usage.dwParam).ID) == ConquerItem.Wing)
                        if (client.Entity.Tournament_Signed)
                            return;
            if (!client.Equipment.Free((byte)usage.dwParam))
                if (IsBow(client.Equipment.TryGetItem((byte)usage.dwParam).ID))
                    client.Entity.RemoveFlag(Update.Flags.Fly);

            if (client.Equipment.Remove((byte)usage.dwParam)) {
                if (client.Map.ID == 1039)
                    client.Entity.AttackPacket = null;
                client.CalculateStatBonus();
                client.CalculateHPBonus();
                client.LoadItemStats();
                var equips = new ClientEquip();
                equips.DoEquips(client);
                client.Send(equips);
            }
        }

        static bool EquipPassLvlReq(ConquerItemBaseInformation baseInformation, GameState client) {
            if (client.Entity.Level < baseInformation.Level)
                return false;
            else
                return true;
        }

        static bool EquipPassRbReq(ConquerItemBaseInformation baseInformation, GameState client) {
            if (baseInformation.Level < 71 && client.Entity is { Reborn: > 0, Level: >= 70 })
                return true;
            else
                return false;
        }

        static bool EquipPassStatsReq(ConquerItemBaseInformation baseInformation, GameState client) {
            if (client.Entity.Strength >= baseInformation.Strength && client.Entity.Agility >= baseInformation.Agility)
                return true;
            else
                return false;
        }

